%         set_param('mpc_ttype_psm/inv_psm_mod1/inverter/inverter/three_phase_inverter_ideal_switch_based_model', 'Commented', 'off');
%     end
% end

if use_torque_curve
    set_param('mpc_ttype_psm/fixed_speed_setting', 'Commented', 'off');
    set_param('mpc_ttype_psm/motor_load_setting', 'Commented', 'on');
else
    set_param('mpc_ttype_psm/fixed_speed_setting', 'Commented', 'on');
    set_param('mpc_ttype_psm/motor_load_setting', 'Commented', 'off');
end


